/// saturating add
macro_rules! RARE_EVENT_INTERP_INC {
    ($interp:expr, $name:ident) => {
        loop {
            let val: u8 = unsafe { (*$interp).rare_events.$name };
            if (val as i32) < 255 {
                FT_ATOMIC_STORE_UINT8!((*$interp).rare_events.$name, (val as i32).wrapping_add(1));
            }
            RARE_EVENT_STAT_INC!();
            if true {
                break;
            }
        }
    };
}

